INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Everest VR', 'Created by Sólfar and RVX, EVEREST VR is one of the most spectacular use cases of virtual reality yet. Preparing for your expedition at Basecamp, you will traverse the Khumbu Icefalls, scale Lhotse Face, ascend the Hillary Step, and finally conquer the summit of Everest. You will learn to respect the mountain, you may even survive the encounter. You will leave the experience feeling like you were there.' FROM games WHERE igdb_id = 18971 ON CONFLICT (game_id, language_code) DO NOTHING;
