INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Egg, Inc.', 'Egg, Inc. is a mobile idle simulation game where players build and manage a futuristic egg farm. The goal is to hatch chickens, expand housing, upgrade vehicles, and research technologies to maximize egg production. As players progress, they unlock increasingly valuable egg types tied to scientific and economic breakthroughs. The game combines incremental mechanics with light management strategy, featuring contracts, missions, and prestige resets that encourage long‑term progression.' FROM games WHERE igdb_id = 58133 ON CONFLICT (game_id, language_code) DO NOTHING;
