INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castles of Mad King Ludwig', 'Castles of Mad King Ludwig, a castle-building board game, tasks players with building extravagant castles for King Ludwig of Bavaria. Castles are constructed one room at a time, with a different player each round setting the prices for the others, resulting in a competitive, engaging game where building is as much fun as winning!
