INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shu', 'Shu will challenge and delight players with an engrossing 2.5D world, filled with collectables, obstacles and threats. Adventure across the land with the help of hand-drawn characters and their unique powers, forever pursued by a monstrous and unrelenting storm. Shu harkens back to old school platforming classics, but also adds its own unique flavour to the formula, boasting a large cast of characters and variety of fast-paced gameplay, optional time-trials and online leaderboards.' FROM games WHERE igdb_id = 24838 ON CONFLICT (game_id, language_code) DO NOTHING;
