INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atomic Butcher: Homo Metabolicus', '"That game where you can pee, poop and puke." -- this is a 2D platformer with 360° aiming. It is violent, it is fast, it is absolutely over the top. Jump around, slide, dash and dunk into enemies to kill them, and then eat them. On your quest for meat you encounter a lot of deadly traps in a post-apocalyptic wasteland. Become the ultimate weapon of mass digestion: the Homo Metabolicus!' FROM games WHERE igdb_id = 25223 ON CONFLICT (game_id, language_code) DO NOTHING;
