INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stop Online: Battle of Words', 'Stop Online is a multiplayer battle of words game where you compete with several players aiming to challenge them on their knowledge of words, trying to be the quickest to respond in order to achieve the highest rank. The words are in your language and you will challenge players in the same language. Languages currently supported are English, Portuguese, Spanish, French, German, Italian, Russian, Turkish, Czech, Dutch and Polish.' FROM games WHERE igdb_id = 34353 ON CONFLICT (game_id, language_code) DO NOTHING;
