INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toy Odyssey: The Lost and Found', 'Toy Odyssey: The Lost and Found is a Metroidvania style action-platformer that takes you back to a world made from the nightmares of your childhood. Join Brand - an action figure that has come to life - in his fight against the darkness to save his owner, Felix. Nightmares are only the start of his troubles: Brand needs to uncover the secrets of the house before it''s too late.' FROM games WHERE igdb_id = 23985 ON CONFLICT (game_id, language_code) DO NOTHING;
