INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Green Game: TimeSwapper', 'It’s a challenging 2D arcade game where you are a master of time. Set it to past, present or future to control various mechanisms, and make sure that a mechanical bird will safely reach the end of the level. Prepare to die a lot – you will be sliced, squashed and crushed.' FROM games WHERE igdb_id = 33753 ON CONFLICT (game_id, language_code) DO NOTHING;
