INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocket League: Collector''s Edition', 'Rocket League is futuristic Sports-Action game, in which players are equipped with booster-rigged vehicles that can be crashed into balls for incredible goals or epic saves across multiple, highly-detailed arenas. Using an advanced physics system to simulate realistic interactions, Rocket League relies on mass and momentum to give players a complete sense of intuitive control in this unbelievable, high-octane re-imagining of association football.' FROM games WHERE igdb_id = 41620 ON CONFLICT (game_id, language_code) DO NOTHING;
