INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WWE Slam', 'Collect & trade your favorite WWE superstars with fans across the world in Topps WWE SLAM! Build the ultimate digital collection featuring the biggest names in wrestling, both past legends and current stars by ripping Topps WWE digital packs – all from your mobile device. Celebrate WWE events with exclusive content releases, original artwork, digitally autographed collectibles, and join in-app Challenges for a chance to win physical Topps WWE card product & more!' FROM games WHERE igdb_id = 57378 ON CONFLICT (game_id, language_code) DO NOTHING;
