INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Icey', 'Icey is a 2D side-scrolling action game and a meta game in disguise. As you follow the narrator''s omnipresent voice, you will see through Icey''s eyes and learn the truth about her world. The narrator will constantly urge you in one direction, but you must ask, "Why? Why am I following his directions?“ Obey? Rebel?' FROM games WHERE igdb_id = 25964 ON CONFLICT (game_id, language_code) DO NOTHING;
