INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wands', 'Wands is a first-person VR experience that offers fast-paced magic duels against other players online. Choose your favourite wands and equip them with a variety of unique spells, then battle other Wielders in the fantastic realms of The Beyond. Hone your skills against an increasingly challenging AI opponent, then duel players from around the world to climb the leaderboards. Between battles, discover new spells, unlock new characters, and build powerful loadouts in your secret workshop.' FROM games WHERE igdb_id = 56982 ON CONFLICT (game_id, language_code) DO NOTHING;
