INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom: New Lands', '"Tales spread of far off isles with mysteries waiting to be discovered. Rulers will need all the strength of their subjects to sail away and find new kingdoms in these New Lands.
