INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Otherland', 'Otherland is an Unreal-powered action-MMORPG based on Tad Williams highly acclaimed novels. Embark on exciting adventures in a virtual multiverse where you fight the Red Queen''s army in the medieval 8Squared, explore Mars, hunt on Bug World or socialize in the bars of futuristic Lambda Mall.' FROM games WHERE igdb_id = 23637 ON CONFLICT (game_id, language_code) DO NOTHING;
