INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tattletail', 'Tattletail is a short, story-driven first person horror game about everyone''s favorite talking toy from the 90''s. You opened your Tattletail before Christmas, and now he won''t stay in his box. Can you keep him out of trouble until Christmas day? Or will Mama Tattletail find her baby and hunt you down first? I heard she was recalled after she ate a kid''s eyes out. Just a rumor.' FROM games WHERE igdb_id = 26665 ON CONFLICT (game_id, language_code) DO NOTHING;
