INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crush Your Enemies', 'Strategy games have become too stuffy, bogged down with diplomacy, endless repositioning, waiting....ugh, so much waiting. Crush Your Enemies is a RTS distilled down to the basics - foul-mouthed barbarians, gratuitous use of "bollocks," and more chest hair than you can handle.' FROM games WHERE igdb_id = 17027 ON CONFLICT (game_id, language_code) DO NOTHING;
