INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carnival Games VR', 'Carnival Games VR brings an immersive virtual reality experience, allowing you to explore the park, interact with patrons and play up to 12 different games. Enter a themed Carnival Alley where you can play a game and earn tickets for virtual prizes or unlock another game. Whether it''s scaling a castle in Climbing Wall or rolling for a high score in Alley Ball - there is a game for everyone!' FROM games WHERE igdb_id = 25339 ON CONFLICT (game_id, language_code) DO NOTHING;
