INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Plantera', 'In the world of Plantera you grow your own garden and breed plants and animals to earn coins with their produce. Use the coins to buy new plants and animals, and also special items and garden expansions. Watch everything grow, help planting and harvesting, buy new things, and defend your garden from sneaky magpies, rabbits, foxes, and wolves. Raise your level and the productivity of your plants and animals! Earn more and more, and create your own dream garden!' FROM games WHERE igdb_id = 17004 ON CONFLICT (game_id, language_code) DO NOTHING;
