INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grand Theft Auto V: Premium Online Edition & Whale Shark Card Bundle', 'The Grand Theft Auto V: Premium Online Edition & Whale Shark Card Bundle includes the complete Grand Theft Auto V story experience, free access to the ever evolving Grand Theft Auto Online and all existing gameplay upgrades and content including The Doomsday Heist, Gunrunning, Smuggler’s Run, Bikers and much more. You’ll also get the Criminal Enterprise Starter Pack, the fastest way to jumpstart your criminal empire in Grand Theft Auto Online, plus a Whale Shark Cash Card worth $3,500,000 in-game GTA dollars to spend in GTA Online.
