INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spaceplan', 'SPACEPLAN is an experimental piece of interaction based partly on a total misunderstanding of Stephen Hawking’s A Brief History of Time. Use manual clicks and the passage of time to create and launch potato-based devices and probes from your nondescript satellite orbiting a mysterious planet. Unlock the mysteries of the galaxy or just kill some time in what the astrophysics community is calling the ‘best narrative sci-fi clicker game of all times’.' FROM games WHERE igdb_id = 28454 ON CONFLICT (game_id, language_code) DO NOTHING;
