INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NeuroVoider', 'NeuroVoider is a twin-stick shooter RPG set in a cyber futuristic world about brains shooting around evil robots with nuclear rocket launchers. Battle through the horde of vigilant robots, boost your character with the smoking remains of your victims, and defeat the master NeuroVoider to end this eternal war. Play it coop with up to 4 friends, or go alone in an adventure of hack''n''slash rampage, with a pinch of rogue-lite, and some permadeath.' FROM games WHERE igdb_id = 23581 ON CONFLICT (game_id, language_code) DO NOTHING;
