INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HordeZ', 'If you are looking for a on-rails arcade experience that blends between classics like Doom, Left 4 dead and House of the Dead then we got you covered! Fast and simple gameplay that will bring you into a creepy world of zombies and demons. Show your skills to the world through our global leadboard system! Bring a friend in multiplayer Co-Op game and send those zombies flying back to hell!' FROM games WHERE igdb_id = 34197 ON CONFLICT (game_id, language_code) DO NOTHING;
