INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gunscape', 17010, '2016-03-01', 55, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1uat.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/armt9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gunscape', 'Gunscape provides a toolbox full of inconic weapons, monsters and level elements as the foundation for players to build co-op, and single-player, FPS levels or MP Arenas in the most intuitive way possible. It does so by offering a series of simple tools based on a block-placement interface that many gamers will be familiar with. Unlike similar tools Gunscape aims to empower its authors to enjoy the process of abstract level design by imposing refreshing restraints that map communities enjoy. Rather than building a game players will build a level within a game that features robust action and a vast array of weapons, enemies and components.' FROM games WHERE igdb_id = 17010 ON CONFLICT (game_id, language_code) DO NOTHING;
