INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('stories-the-path-of-destinies', 12815, '2016-04-12', 71, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co248w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1cek.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stories: The Path of Destinies', 'Reynardo the Fox is a clever rogue, but he’s not as clever as he thinks. He''s got himself sucked into a Rebellion against the mad Emperor, and now he’s got fateful choices to make. Should he rescue his oldest friend, the shiftless Lapino; wield a gem cursed by a dead god; or resurrect a weapon lost at the beginning of time? Worse, he’s still in love with the Emperor’s adopted daughter, who he met in sword fu school. He’s got dozens of ways to screw this up; but is can he find a way to win his war?
