INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Hulk: Deathwing', 'Space Hulk: Deathwing is a First-Person Shooter experience of Games Workshop''s classic Space Hulk boardgame set in the universe of Warhammer 40,000, developed on Unreal Engine 4 by Streum On Studio, the team behind E.Y.E: Divine Cybermancy. Published by Focus Home Interactive and co-produced by Cyanide Studio, Space Hulk: Deathwing offers players the chance to experience a desperate battle against Genestealers in the claustrophobic tunnels of a Space Hulk, as they will gain skills, new abilities and new equipment thanks to experience earned during perilous missions.
