INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brigador', 'Brigador is an isometric vehicle action game set in completely destructible environments. Highly difficult without being unfair. Lush revivalist graphic style reminds you of what 90''s games would look like now. Huge variety of playable vehicles and weapons, deep tactics and high skill ceiling with custom map support all contribute to a game built to be played and enjoyed for a long time.' FROM games WHERE igdb_id = 13361 ON CONFLICT (game_id, language_code) DO NOTHING;
