INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Mims Beginning', 'Experience the mysterious and mystical by taking on a journey with Mims in this strategic god-like game. Create structures, plant vegetation, breed animals, take care of your minions, use divine PSI powers, triumph in face of natural disasters, fight monsters, predict the future, and so much more....it looks like a fairly deep, personality rich god game revival. Given that good god games are in woefully short supply these days, we should probably count our blessings here.' FROM games WHERE igdb_id = 36054 ON CONFLICT (game_id, language_code) DO NOTHING;
