INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MTB Downhill Simulator', 'Welcome to the exciting world of MTB rides! Prepare yourself for the madness of downhill! Dangerous and difficult trails await you. Take your bike and ride! Now you can explore extreme trails and enjoy the thrill of a steep, rough terrain full of rocks and countless obstacles. Dodge or jump over them and reach the finish line as fast as possible! Collect money to improve and customise your own downhill and make it as unique and fast as you can. Get ready for some awesome rides!' FROM games WHERE igdb_id = 53389 ON CONFLICT (game_id, language_code) DO NOTHING;
