INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Janken Cards', 'Janken Cards is a turn based card videogame, influenced by "Rock-Paper-Scissors". The rules are easy: there are 30 cards on the board and you must fill 3 columns with cards of the same suit in order to win. However, if nobody manages to fill 3 columns, then the one who scores the most points becomes the winner.' FROM games WHERE igdb_id = 31320 ON CONFLICT (game_id, language_code) DO NOTHING;
