INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warpin: Creation (VR)', 'Built from the ground up for VR, Warpin: Creation takes you to the midimensions that lie in the warpstreams between our world and others. Recruited by an unknown great one, your combat skills are all that stand between life''s premise and the ultimate unraveling of reality. Journey through endless midimensions, forge weapons, and destroy the flaws that threaten existence.' FROM games WHERE igdb_id = 30724 ON CONFLICT (game_id, language_code) DO NOTHING;
