INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sinful Eden', 'Sinful Eden is a point ''n'' click adventure with dating sim and RPG elements. You take on the role of a young man living in Karigon Island, Karigon law states that all males who''re of age are duty-bound to marry, failure to comply will result in execution, as ordained by the high priestess Aurora. Unfortunately for you, finding a suitable bride isn''t as easy as it sounds... There will be many obstacles in your path to find true love, can you overcome them before it''s too late?' FROM games WHERE igdb_id = 32770 ON CONFLICT (game_id, language_code) DO NOTHING;
