INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Walker', 'Journey your way high and low, far and wide, just for the heck of it. Meet weirdos along the way. Explode things. Explode them good. It''s a super quirky semi-retro platform-adventure.' FROM games WHERE igdb_id = 33388 ON CONFLICT (game_id, language_code) DO NOTHING;
