INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Recourse', 'Recourse is a puzzle game with unprecedented puzzle variety. It''s the story of two A.I. units, Sleet and Floe, trying to discover why they are on a seemingly abandoned ice planet. A playable demo is available for the game. Please visit our website for higher quality videos and more in-depth information.' FROM games WHERE igdb_id = 34138 ON CONFLICT (game_id, language_code) DO NOTHING;
