INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Why is the Princess in a Magic Forest?!', 'Max is on an epic quest to save the legendary princess in the fabled magic forest where anything is possible. The twist? Max is the weakest hero ever to exist! Help Max reach the goal through a legion of levels, all the while having to deal with magic experiments, explosive sheep, friendzoned specters, black-holes and much much more! Why? Because it''s a MAGIC forest after all! Help Max survive all the dangerous hazards in order to find the princess...who may or may not even exist!' FROM games WHERE igdb_id = 31577 ON CONFLICT (game_id, language_code) DO NOTHING;
