INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzle Galaxies', 'Puzzle Galaxies is a groundbreaking puzzle video game similar to games like Bejeweled and Candy Crush. You must match jewels stored in a space station in a manner similar to Bejeweled, but there''s a twist - there are enemies that will come by and try to take matching jewels on you! Racing against the clock, and against the enemies, you must match the jewels in each of the pods of the space station before time runs out.' FROM games WHERE igdb_id = 32936 ON CONFLICT (game_id, language_code) DO NOTHING;
