INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Edge of Nowhere', 'Edge of Nowhere is a VR third-person action-adventure from acclaimed independent developer Insomniac Games. Travel to the far reaches of the Antarctic mountains in search of a missing expedition team. What appears to be a rescue mission takes a turn as you venture into the deep unknown, and discover a surreal world that will test your wits and sanity. Scale towering mountains and use makeshift weapons to survive and avoid descending into madness. In Edge of Nowhere, nothing is what it seems and the unexpected lurks from all sides.' FROM games WHERE igdb_id = 11159 ON CONFLICT (game_id, language_code) DO NOTHING;
