INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Archery by Thornbury Software', 'Archery is an archery tournament with multiple levels ranging from easy indoor target ranges to outdoor target ranges with various animal-shaped targets both moving and stationary. The levels range from easy indoor, sharp-shooter targets, outdoor targets with animal-shaped targets which in several levels move and are more challenging to hit. Get the number of points required in each level to move on to the next level. Just wait until you get to the final levels for a big surprise!' FROM games WHERE igdb_id = 84757 ON CONFLICT (game_id, language_code) DO NOTHING;
