INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Whispered Secrets: Everburning Candle - Collector''s Edition', 'A fire at the local asylum takes on a supernatural life of its own! You’re called in to investigate and find dark and shady dealings behind the scenes, with the lives of several patients at stake. Who are these so-called ‘outcasts,’ and why are they really here? Douse the flames on this mystery as you explore hidden-object puzzles and solve mini-games!' FROM games WHERE igdb_id = 316694 ON CONFLICT (game_id, language_code) DO NOTHING;
