INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel Avengers Academy', 'Marvel Avengers Academy is a mobile simulation game that invites players into a reimagining of the Marvel Universe. Players take on the role of a director tasked with building and managing their own superhero academy, where iconic Marvel characters like Iron Man, Captain America, Black Widow, Hulk, Thor, and many others are reimagined as students. As the academy grows, players can unlock new characters, outfits, and abilities, while also expanding their campus and completing missions to advance the storyline.' FROM games WHERE igdb_id = 18028 ON CONFLICT (game_id, language_code) DO NOTHING;
