INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Defenders of the Last Colony', 'Defenders of the Last Colony is a Top Down Shooter with Strategy gameplay mechanics, where you have to protect the Colony''s core while you gather resources and build defenses. You play as one of the 4 classes: Fighter, Engineer, Striker or Carrier. Defenders features coop up to 4 players and 3D graphics.' FROM games WHERE igdb_id = 36208 ON CONFLICT (game_id, language_code) DO NOTHING;
