INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Splat the Difference', 'Splat! This spot the difference game is extra messy! When you find a difference, splat it with paint! Play solo or battle it out with friends! Up to four can play with just one copy of the game using Download Play. With hundreds of pictures and differences that change each time you play, the puzzles never repeat.' FROM games WHERE igdb_id = 86257 ON CONFLICT (game_id, language_code) DO NOTHING;
