INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spikit', 'Spikit is a bullet hell game developed by a single developer, Igor Petrović. With a soundtrack composed by Dario Malešević. In this game, the player will have to dodge a constant barrage of spikes coming from the side of the screen. Not only will the player have to evade the spikes currently on the screen, but they will also need to keep an eye out on the next wave of spikes and position themselves accordingly.' FROM games WHERE igdb_id = 31867 ON CONFLICT (game_id, language_code) DO NOTHING;
