INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '5 Star Wrestling: ReGenesis', '5 Star Wrestling: ReGenesis is built on true Ring Psychology with Heel and Face mechanics, a revolutionary Limb Damage System and Rivalries that impact gameplay. Featuring a 40 Hour Challenge campaign with 128 challenges, over 400 objectives, and more moves-per-wrestler than any other game including never before seen Finisher-To-Finisher reversals, 5 Star Wrestling is brimming with content.
