INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blackguards: Definitive Edition', 'Blackguards is a role-playing game which focuses on tactical combat. It leaves the high-fantasy parts of Aventuria which is usually found in The Dark Eye games and is set in the wild south (Mengbilla, Loch Harodrôl and The Green Hell). The player character has memory loss and is accused of murdering a princess. The next course of action is breaking out of prison, picking up some other criminals as party members and finding out what happened. Parts of the story are told in flashbacks.' FROM games WHERE igdb_id = 206292 ON CONFLICT (game_id, language_code) DO NOTHING;
