INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CloudBound', 'CloudBound is a VR platformer where the player uses a Grappling Hook gun to swing, climb, and fling their way to the top of each level. Using our DFoV System ("Dynamic Field of View") we''ve managed to dramatically reduce simulation sickness to the point that users can move comfortably at high speeds! Don''t take our word for it, let us know what you think!' FROM games WHERE igdb_id = 31374 ON CONFLICT (game_id, language_code) DO NOTHING;
