INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungenious', 'Dungenious lets you battle monsters while you learn. Upgrade your hero along with your mind with a mix of flashcards, quizzes, and dungeons. No need to procrastinate with games while you study - use Dungenious to learn! More than 50 topics are included, but you can also add your own questions to make play time educational! Study for class, challenge your friends, and learn the fun way.' FROM games WHERE igdb_id = 187782 ON CONFLICT (game_id, language_code) DO NOTHING;
