INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ascending Pinball', 'A minimalistic casual pinball. A classic genre revamp with an endless table. The objective is to overcome the largest amount of levels you can, flipper over flipper. During the journey we’ll run into moving barriers, targets, bonus multipliers, ball savers, jackpots... a lot of the classical elements of pinball with a new twist in the game mechanic.' FROM games WHERE igdb_id = 26684 ON CONFLICT (game_id, language_code) DO NOTHING;
