INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swap Fire', 'Swap Fire''s a shooter with a literal twist. Shooting other players rips a hole in spacetime thus swapping your locations. You''ll have to commit to losing in order to win in Drop Zone, manage spacetime to dominate the map in Control Point, master the art of teleportation to go for the gold in Swoccer, and much more!' FROM games WHERE igdb_id = 77773 ON CONFLICT (game_id, language_code) DO NOTHING;
